package com.ias.identity.auth;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class StockEngineerQualificationTest {
 JdbcTemplate db;
 @BeforeEach void prepare(){db=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1","sa",""));db.execute("CREATE TABLE tenant(id BIGINT,status INT);CREATE TABLE identity_department(id BIGINT,tenant_id BIGINT,enabled INT);CREATE TABLE identity_user(id BIGINT,tenant_id BIGINT,department_id BIGINT,identity_type VARCHAR(20),status INT,must_change_password INT);CREATE TABLE identity_user_capability(user_id BIGINT,capability_code VARCHAR(50),enabled INT)");db.update("INSERT INTO tenant VALUES(7,1)");db.update("INSERT INTO identity_department VALUES(5,7,1)");db.update("INSERT INTO identity_user VALUES(42,7,5,'EMPLOYEE',1,0)");for(String c:List.of("ticket.engineer.read","ticket.record","ticket.assignment.accept"))db.update("INSERT INTO identity_user_capability VALUES(42,?,1)",c);}
 boolean eligible(){return Boolean.TRUE.equals(StockEngineerQualificationController.facts(db,7,42,5).get("eligible"));}
 @Test void currentExplicitQualificationBindsAllIds(){var f=StockEngineerQualificationController.facts(db,7,42,5);assertTrue(eligible());assertEquals("7",f.get("tenantId"));assertEquals("42",f.get("userId"));assertEquals("5",f.get("departmentId"));assertNotNull(f.get("checkedAt"));assertEquals(false,StockEngineerQualificationController.facts(db,8,42,5).get("eligible"));assertEquals(false,StockEngineerQualificationController.facts(db,7,42,6).get("eligible"));}
 @Test void eachCapabilityRevocationImmediatelyDenies(){for(String c:List.of("ticket.engineer.read","ticket.record","ticket.assignment.accept")){db.update("UPDATE identity_user_capability SET enabled=0 WHERE capability_code=?",c);assertFalse(eligible());db.update("UPDATE identity_user_capability SET enabled=1 WHERE capability_code=?",c);assertTrue(eligible());}}
 @Test void tenantDepartmentAndUserDisableAreCurrentFacts(){db.update("UPDATE tenant SET status=0");assertFalse(eligible());db.update("UPDATE tenant SET status=1");db.update("UPDATE identity_department SET enabled=0");assertFalse(eligible());db.update("UPDATE identity_department SET enabled=1");db.update("UPDATE identity_user SET department_id=6");assertFalse(eligible());db.update("UPDATE identity_user SET department_id=5,status=0");assertFalse(eligible());}
 @Test void restrictedCustomerOrWarehouseManagerCannotBecomeEngineer(){db.update("UPDATE identity_user SET must_change_password=1");assertFalse(eligible());db.update("UPDATE identity_user SET must_change_password=0,identity_type='CUSTOMER'");assertFalse(eligible());db.update("UPDATE identity_user SET identity_type='EMPLOYEE'");db.update("DELETE FROM identity_user_capability");db.update("INSERT INTO identity_user_capability VALUES(42,'stock.manage',1)");assertFalse(eligible());}
 @Test void strictIdentifiersRejectOverflowZeroAndNumbers(){for(Object n:List.of("0","01","9223372036854775808",42,"-1"))assertThrows(Exception.class,()->StockEngineerQualificationController.positive(n));assertEquals(42,StockEngineerQualificationController.positive("42"));}
}
